export async function listTools() {
  return [
    {
      name: 'order_status',
      description: 'Get the current status of an order, optionally including chronological history.',
      inputSchema: {
        type: 'object',
        properties: {
          order_id: { type: 'string', description: 'The order identifier.' },
          include_history: { type: 'boolean', description: 'Whether to include chronological history.', default: false }
        },
        required: ['order_id'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    throw new Error('Unknown tool: ' + name);
  }
  // validate args
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const allowed = new Set(['order_id', 'include_history']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error('Unknown field: ' + key);
    }
  }
  if (!('order_id' in args)) {
    throw new Error('Missing required field: order_id');
  }
  const orderId = args.order_id;
  if (typeof orderId !== 'string') {
    throw new Error('order_id must be a string');
  }
  let includeHistory = false;
  if ('include_history' in args) {
    if (typeof args.include_history !== 'boolean') {
      throw new Error('include_history must be a boolean');
    }
    includeHistory = args.include_history;
  }
  const order = orders[orderId];
  if (!order) {
    throw new Error('Order not found: ' + orderId);
  }
  let text = 'status: ' + order.status;
  if (includeHistory) {
    text += '\nhistory: ' + order.history.join(', ');
  }
  return { content: [{ type: 'text', text }] };
}
